import assert from 'node:assert/strict';
import { Agent, Connector, ContextCompactionStrategy, Vendor, MessageRole, ContentType } from '/Users/aantich/dev/oneringai/dist/index.js';
const usage={input_tokens:80,output_tokens:20,total_tokens:100};
const message=(role,text)=>({type:'message',role,content:[{type:role==='assistant'?'output_text':'input_text',text}]});
function setup(name, config={}, extras={}) {
 const calls={main:0,native:0,count:0,hooks:0};
 const provider={name:'offline-review-provider',capabilities:{text:true,images:false,videos:false,audio:false},
 generate:async o=>{calls.main++;return {id:'answer',object:'response',created_at:1,model:o.model,status:'completed',output_text:'DONE',output:[message('assistant','DONE')],usage};},
 async *streamGenerate(){throw new Error('unused');},
 compaction:{compact:async()=>{calls.native++;return {protocol:'review-native-v1',usage,input:[{type:'compaction',id:'cmp',encrypted_content:'OPAQUE'}]};},
 countInput:async o=>{calls.count++;return o.input.some(i=>i.type==='compaction')?1000:4800;}},
 getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:32000,maxInputTokens:32000,maxOutputTokens:512}),validateConfig:async()=>true,listModels:async()=>[]};
 Connector.create({name,vendor:Vendor.OpenAI,auth:{type:'none'},options:{provider}});
 const agent=Agent.create({connector:name,model:'fixture',userId:'owner',modelExecution:{customProviderAttempts:'single'},...extras,
 context:{model:'fixture',maxContextTokens:5000,responseReserve:100,criticalCompactionThreshold:.7,
 features:{workingMemory:false,inContextMemory:true,evidence:true},compactionStrategy:new ContextCompactionStrategy({plugins:'off',history:'native',...config})}});
 for(let i=0;i<5;i++){agent.context.addUserMessage(`USER_${i}`);agent.context.addAssistantResponse([message('assistant','OLD_DETAIL '.repeat(220))]);}
 return {agent,calls,provider};
}
const results=[];
let f;
f=setup('hook-preservation',{}, {lifecycleHooks:{beforeCompaction:async()=>{f.calls.hooks++;f.agent.context.getPlugin('in_context_memory').set('saved-fact','Critical preservation','EXACT_FACT');}}});
try { let error;try{await f.agent.run('Next');}catch(e){error={message:e.message,code:e.code};}
 results.push({case:'beforeCompaction saves built-in memory',error,calls:f.calls,saved:JSON.stringify(f.agent.context.getPlugin('in_context_memory').getState()).includes('EXACT_FACT')});
 assert.equal(f.calls.hooks,1);assert.equal(f.calls.native,0);assert.match(error.message,/changed during preparation/);
}finally{f.agent.destroy();}
console.log(JSON.stringify(results,null,2));
f=setup('hook-control');
try {await f.agent.run('Next');assert.equal(f.calls.native,1);assert.equal(f.calls.main,1);console.log(JSON.stringify({case:'unchanged hook control',calls:f.calls}));}finally{f.agent.destroy();}
f=setup('cancel-source-read');
try {
 await f.agent.compactContext();
 const store=f.agent.context.getPlugin('evidence').storage;
 const originalRead=store.readRecord.bind(store);
 let entered,release;
 const started=new Promise(resolve=>{entered=resolve;});
 const wait=new Promise(resolve=>{release=resolve;});
 store.readRecord=async reference=>{entered();await wait;return originalRead(reference);};
 let outcome='pending'; const operation=f.agent.run('Next').then(()=>{outcome='resolved';},e=>{outcome=e.message;});
 await started;f.agent.cancel('CANCEL_SOURCE_READ');await new Promise(resolve=>setTimeout(resolve,50));
 let concurrentError;try{await f.agent.run('Concurrent');}catch(e){concurrentError=e.message;}
 const beforeRelease={outcome,concurrentError,calls:{...f.calls}};
 assert.equal(outcome,'pending');assert.match(concurrentError,/active run/);assert.equal(f.calls.main,0);
 release();await operation;console.log(JSON.stringify({case:'source proof read cancellation',beforeRelease,afterRelease:outcome}));
}finally{f.agent.destroy();}
const {ModelTask,StrategyRegistry}=await import('/Users/aantich/dev/oneringai/dist/index.js');
f=setup('legacy-hook-control',{}, {lifecycleHooks:{beforeCompaction:async()=>{f.calls.hooks++;f.agent.context.getPlugin('in_context_memory').set('saved-fact','Critical preservation','EXACT_FACT');}}});
try{f.agent.context.setCompactionStrategy(StrategyRegistry.create('algorithmic'));await f.agent.run('Next');console.log(JSON.stringify({case:'algorithmic hook compatibility control',calls:f.calls}));assert.equal(f.calls.main,1);assert.equal(f.calls.hooks,1);}finally{f.agent.destroy();}
f=setup('deadline-source-read');
let task;
try{
 await f.agent.compactContext();
 const store=f.agent.context.getPlugin('evidence').storage,read=store.readRecord.bind(store);
 let entered,release;const started=new Promise(r=>{entered=r;}),wait=new Promise(r=>{release=r;});
 store.readRecord=async reference=>{entered();await wait;return read(reference);};
 task=new ModelTask({limits:{deadline:Date.now()+30}});
 let outcome='pending';const operation=f.agent.run('Next',{modelTask:task}).then(()=>{outcome='resolved';},e=>{outcome=e.message;});
 await started;await new Promise(r=>setTimeout(r,70));
 const beforeRelease={outcome,taskAborted:task.signal.aborted,calls:{...f.calls}};
 assert.equal(outcome,'pending');assert.equal(task.signal.aborted,true);assert.equal(f.calls.main,0);
 release();await operation;console.log(JSON.stringify({case:'source proof read deadline',beforeRelease,afterRelease:outcome}));
}finally{task?.destroy();f.agent.destroy();}
Connector.clear();
f=setup('stream-hook-preservation',{}, {lifecycleHooks:{beforeCompaction:async()=>{f.calls.hooks++;f.agent.context.getPlugin('in_context_memory').set('saved-fact','Critical preservation','EXACT_FACT');}}});
try{
 let error;try{for await(const event of f.agent.stream('Next')){/* drain */}}catch(e){error={message:e.message,code:e.code};}
 assert.equal(f.calls.hooks,1);assert.equal(f.calls.native,0);assert.match(error.message,/changed during preparation/);
 console.log(JSON.stringify({case:'stream beforeCompaction saves built-in memory',error,calls:f.calls}));
}finally{f.agent.destroy();}
f=setup('manual-cancel-source-read');
try {
 await f.agent.compactContext();
 const store=f.agent.context.getPlugin('evidence').storage,read=store.readRecord.bind(store);
 let entered,release;const started=new Promise(r=>{entered=r;}),wait=new Promise(r=>{release=r;});
 store.readRecord=async reference=>{entered();await wait;return read(reference);};
 const controller=new AbortController();let outcome='pending';
 const operation=f.agent.compactContext({signal:controller.signal}).then(()=>{outcome='resolved';},e=>{outcome=e.message;});
 await started;controller.abort(new Error('CANCEL_MANUAL_PROOF'));await new Promise(r=>setTimeout(r,50));
 const beforeRelease={outcome,signalAborted:controller.signal.aborted,calls:{...f.calls}};
 assert.equal(outcome,'pending');assert.equal(f.calls.native,1);
 release();await operation;console.log(JSON.stringify({case:'manual source proof read cancellation',beforeRelease,afterRelease:outcome}));
}finally{f.agent.destroy();}
Connector.clear();

import assert from 'node:assert/strict';
import fs from 'node:fs';
import { Agent, Connector, ContextCompactionStrategy, Vendor } from '/Users/aantich/dev/oneringai/src/index.ts';
const sent=[];
const originalFetch=globalThis.fetch;
globalThis.fetch=async(input,init)=>{
 const url=String(input instanceof Request?input.url:input);
 const body=url.includes('/models/')?undefined:input instanceof Request?await input.clone().json():JSON.parse(String(init?.body));
 sent.push({url,body});
 let value;
 if(url.includes('/models/'))value={id:'claude-sonnet-4-6',capabilities:{compaction:{supported:true,summarize:{supported:true}}}};
 else if(url.includes('count_tokens'))value={input_tokens:JSON.stringify(body).includes('"type":"compaction"')?200:1000};
 else value={id:'msg_c',type:'message',role:'assistant',model:'claude-sonnet-4-6',stop_reason:'compaction',content:[{type:'compaction',content:'SIGNED_SUMMARY',signature:'SIGNATURE'}],usage:{iterations:[{type:'compaction',input_tokens:1000,output_tokens:50,cache_read_input_tokens:0,cache_creation_input_tokens:0}]}};
 return new Response(JSON.stringify(value),{headers:{'content-type':'application/json'}});
};
Connector.create({name:'reasoning-review',vendor:Vendor.Anthropic,auth:{type:'api_key',apiKey:'synthetic-offline'},baseURL:'https://synthetic.invalid',options:{maxRetries:0}});
const agent=Agent.create({connector:'reasoning-review',model:'claude-sonnet-4-6',context:{model:'claude-sonnet-4-6',features:{workingMemory:false,inContextMemory:false,evidence:true},compactionStrategy:new ContextCompactionStrategy({plugins:'off',history:{mode:'native',preserveRecentTurns:0}})}});
try{
 agent.context.addUserMessage('Prior user');
 agent.context.addAssistantResponse([{type:'reasoning',id:'r',summary:'VISIBLE_REASONING_FACT',encrypted_content:'OPAQUE_PROVIDER_STATE'}, {type:'message',role:'assistant',content:[{type:'output_text',text:'Prior answer'}]}]);
 const before=structuredClone(agent.context.getState());
 const report=await agent.compactContext();
 const after=structuredClone(agent.context.getState());
 const result={case:'Anthropic source with unsupported top-level reasoning',report,beforeTypes:before.conversation.map(i=>i.type),afterTypes:after.conversation.map(i=>i.type),nativeRequest:sent.find(s=>s.body?.compaction)?.body,countedFrames:sent.filter(s=>s.url.includes('count_tokens')).map(s=>s.body),reasoningOnWire:JSON.stringify(sent).includes('VISIBLE_REASONING_FACT')||JSON.stringify(sent).includes('OPAQUE_PROVIDER_STATE')};
 assert.equal(report.history.status,'compacted');assert.equal(result.reasoningOnWire,false);assert.ok(!after.conversation.some(i=>i.type==='reasoning'));
 fs.writeFileSync('/tmp/stage16-second-review-anthropic.json',JSON.stringify(result,null,2));
 console.log(JSON.stringify({case:result.case,status:report.history.status,beforeTypes:result.beforeTypes,afterTypes:result.afterTypes,reasoningOnWire:result.reasoningOnWire}));
}finally{agent.destroy();Connector.clear();globalThis.fetch=originalFetch;}
